1	/**
2	 * Effective-dated budget versions (the budget chronology). Pure helpers over
3	 * BudgetTemplate lines, mirroring the effective-dated mappings pattern the
4	 * category→envelope resolution uses (ISC-19, src/envelope/spend.ts).
5	 *
6	 * DAY-WEIGHTED PRORATION (owner decision, 2026-07-16): a line contributes to
7	 * every month M where month(effectiveFrom) <= M <= month(effectiveTo ?? infinity),
8	 * and its contribution is prorated by the days of M its effective window
9	 * actually covers:
10	 *
11	 *   contribution = round(amountCents * activeDays / daysInMonth)
12	 *
13	 * where activeDays counts the days of M inside [effectiveFrom, effectiveTo ?? open]
14	 * and daysInMonth is the real calendar length (28/29/30/31, leap-Feb correct).
15	 * A line covering the whole month contributes EXACTLY amountCents (activeDays ==
16	 * daysInMonth), so full-month resolution is unchanged from the original
17	 * month-bucket rule. The owner's example: $500/mo through 14 Jul + $600/mo from
18	 * 15 Jul gives July round(50000*14/31) + round(60000*17/31) = 55484 (~$554.84).
19	 * amountCents is already the monthly equivalent for every cadence (the `period`
20	 * field is a display label — see contract.ts BudgetVersionView), so proration
21	 * scales it directly with no cadence maths.
22	 *
23	 * A month's budget for an envelope is the SUM of all contributing lines'
24	 * prorated amounts, so two OPEN versions both covering the full month still
25	 * fully combine (the original overlap-sums rule is intact). A legacy line with
26	 * no dates reads as effectiveFrom '1970-01-01' / open-ended, which resolves
27	 * identically to the pre-versioning template for every month.
28	 *
29	 * No I/O and no clock reads: callers pass the month (and "now") explicitly, so
30	 * the timezone-correct current period stays derived from src/platform/time.ts
31	 * at the boundary.
32	 */
33	
34	import type { BudgetTemplate, IncomeEnvelope, Period } from "../domain/types.ts";
35	import { comparePeriods, monthBounds, periodOfDate } from "../envelope/period.ts";
36	
37	/** The default effectiveFrom for legacy lines written before versioning. */
38	export const OPEN_EFFECTIVE_FROM = "1970-01-01";
39	
40	/** A line's effectiveFrom with the legacy default applied. */
41	export function effectiveFromOf(line: BudgetTemplate): string {
42	  return line.effectiveFrom ?? OPEN_EFFECTIVE_FROM;
43	}
44	
45	/** A line's effectiveTo with the legacy default (open-ended) applied. */
46	export function effectiveToOf(line: BudgetTemplate): string | null {
47	  return line.effectiveTo ?? null;
48	}
49	
50	/** True when the line contributes to month M (its window touches the month). */
51	export function lineActiveInMonth(line: BudgetTemplate, month: Period): boolean {
52	  if (comparePeriods(periodOfDate(effectiveFromOf(line)), month) > 0) return false;
53	  const to = effectiveToOf(line);
54	  if (to !== null && comparePeriods(periodOfDate(to), month) < 0) return false;
55	  return true;
56	}
57	
58	/** The real calendar length of month M (28/29/30/31; leap Februaries correct). */
59	export function daysInMonth(month: Period): number {
60	  return new Date(Date.UTC(month.year, month.month, 0)).getUTCDate();
61	}
62	
63	/**
64	 * The number of days of month M covered by the line's effective window
65	 * [effectiveFrom, effectiveTo ?? open]. Clamps both ends to the month's bounds;
66	 * ISO YYYY-MM-DD strings compare correctly as strings, so this is pure string
67	 * arithmetic plus a day-of-month subtraction. Zero when the window misses M.
68	 */
69	export function activeDaysInMonth(line: BudgetTemplate, month: Period): number {
70	  const { first, last } = monthBounds(month);
71	  const from = effectiveFromOf(line);
72	  const to = effectiveToOf(line) ?? last;
73	  const start = from > first ? from : first;
74	  const end = to < last ? to : last;
75	  if (start > end) return 0;
76	  return Number(end.slice(8, 10)) - Number(start.slice(8, 10)) + 1;
77	}
78	
79	/**
80	 * The line's day-weighted contribution to month M (owner decision, 2026-07-16):
81	 * round(amountCents * activeDays / daysInMonth), integer cents. Exactly
82	 * amountCents for full-month coverage; 0 when the window misses M.
83	 */
84	export function lineContributionForMonth(line: BudgetTemplate, month: Period): number {
85	  const active = activeDaysInMonth(line, month);
86	  if (active === 0) return 0;
87	  const total = daysInMonth(month);
88	  if (active === total) return line.amountCents;
89	  return Math.round((line.amountCents * active) / total);
90	}
91	
92	/** The lines contributing to month M. */
93	export function linesForMonth(
94	  lines: readonly BudgetTemplate[],
95	  month: Period,
96	): BudgetTemplate[] {
97	  return lines.filter((l) => lineActiveInMonth(l, month));
98	}
99	
100	/**
101	 * Month-resolved template: one summed amount per envelope for month M
102	 * (the versioned replacement for applyTemplate). Each line contributes its
103	 * DAY-WEIGHTED prorated amount; overlap within a month SUMS the prorations
104	 * (full-month overlaps still fully sum).
105	 */
106	export function resolveTemplateForMonth(
107	  lines: readonly BudgetTemplate[],
108	  month: Period,
109	): Map<string, number> {
110	  const out = new Map<string, number>();
111	  for (const line of linesForMonth(lines, month)) {
112	    out.set(line.envelopeId, (out.get(line.envelopeId) ?? 0) + lineContributionForMonth(line, month));
113	  }
114	  return out;
115	}
116	
117	/** The summed (day-weighted) month-resolved amount for ONE envelope's lines in month M. */
118	export function resolveAmountForMonth(
119	  lines: readonly BudgetTemplate[],
120	  envelopeId: string,
121	  month: Period,
122	): number {
123	  let sum = 0;
124	  for (const line of lines) {
125	    if (line.envelopeId !== envelopeId) continue;
126	    sum += lineContributionForMonth(line, month);
127	  }
128	  return sum;
129	}
130	
131	/**
132	 * The single line to adjust for an in-place delta edit (move-money /
133	 * distribute keep today's adjust-the-ongoing-plan semantics rather than
134	 * versioning every rebalance): the line contributing to `month` with the
135	 * greatest effectiveFrom, or null when none contributes.
136	 */
137	export function currentLineFor(
138	  lines: readonly BudgetTemplate[],
139	  envelopeId: string,
140	  month: Period,
141	): BudgetTemplate | null {
142	  let best: BudgetTemplate | null = null;
143	  for (const line of lines) {
144	    if (line.envelopeId !== envelopeId) continue;
145	    if (!lineActiveInMonth(line, month)) continue;
146	    if (best === null || effectiveFromOf(line) > effectiveFromOf(best)) best = line;
147	  }
148	  return best;
149	}
150	
151	/**
152	 * Calendar day before an ISO date (pure calendar arithmetic; no timezone is
153	 * involved because both sides are already local calendar dates). Used by
154	 * completePrevious: the previous version ends the day before the new one starts.
155	 */
156	export function previousDay(isoDate: string): string {
157	  const d = new Date(`${isoDate}T00:00:00Z`);
158	  d.setUTCDate(d.getUTCDate() - 1);
159	  return d.toISOString().slice(0, 10);
160	}
161	
162	/**
163	 * An income envelope's monthly budget for month M. Income budgets version
164	 * through the SAME effective-dated template lines (keyed by the income envelope
165	 * id). An income with no version lines at all falls back to the stored
166	 * `budgetedCents` (legacy back-compat: income budgets predate versioning).
167	 *
168	 * Resolution is EXPECTED-DAY based, never day-prorated (owner directive
169	 * 2026-08-12: "income comes in all at once on a given day — pro-rating it
170	 * doesn't make sense"): the month's budget is the full amount of the version
171	 * in force on the month's expected receipt day (expectedDay, default day 1,
172	 * clamped to the month's length). A month whose expected day falls in no
173	 * version's window expects 0.
174	 */
175	export function resolveIncomeBudgetForMonth(
176	  lines: readonly BudgetTemplate[],
177	  income: IncomeEnvelope,
178	  month: Period,
179	): number {
180	  let hasLines = false;
181	  let onDay: BudgetTemplate | null = null;
182	  const day = Math.min(income.expectedDay ?? 1, daysInMonth(month));
183	  const date = `${String(month.year).padStart(4, "0")}-${String(month.month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
184	  for (const line of lines) {
185	    if (line.envelopeId !== income.id) continue;
186	    hasLines = true;
187	    const from = effectiveFromOf(line);
188	    const to = effectiveToOf(line);
189	    if (from <= date && (to === null || to >= date)) onDay = line;
190	  }
191	  if (!hasLines) return income.budgetedCents;
192	  return onDay === null ? 0 : onDay.amountCents;
193	}
194	
195	/** Version status against the current (timezone-derived) month. */
196	export type VersionStatus = "completed" | "active" | "scheduled";
197	
198	export function versionStatus(line: BudgetTemplate, now: Period): VersionStatus {
199	  if (comparePeriods(periodOfDate(effectiveFromOf(line)), now) > 0) return "scheduled";
200	  const to = effectiveToOf(line);
201	  if (to !== null && comparePeriods(periodOfDate(to), now) < 0) return "completed";
202	  return "active";
203	}
