1	/**
2	 * The zero-based check and income variance (ISC-30, ISC-31, ISC-32, ISC-65).
3	 *
4	 * The ISA's final resolution (Changelog, 2026-06-26): zero-based applies to the
5	 * PLAN, not to actual cash. The check compares total spending allocations to
6	 * total BUDGETED income and raises an alert on any imbalance. It NEVER blocks a
7	 * save or a view (ISC-32 anti). Income variance is a separate, first-class idea:
8	 * each income envelope carries budgeted vs actual, and the difference is the
9	 * surplus/deficit on that envelope (ISC-31, ISC-65).
10	 *
11	 * Pure functions. No I/O.
12	 */
13	
14	import type { IncomeEnvelope } from "../domain/types.ts";
15	
16	export interface ZeroBasedState {
17	  readonly budgetedIncomeCents: number;
18	  readonly allocatedCents: number;
19	  /** budgetedIncome - allocated. Positive = unallocated, negative = over-allocated. */
20	  readonly unallocatedCents: number;
21	  /** True on any imbalance. An alert, never a block (ISC-30). */
22	  readonly zeroBasedAlert: boolean;
23	}
24	
25	/**
26	 * Compare total budgeted income to total spending allocations (ISC-30).
27	 * `allocationsByEnv` is the period's direct allocation per spending envelope.
28	 */
29	export function zeroBasedCheck(
30	  incomeEnvelopes: readonly IncomeEnvelope[],
31	  allocationsByEnv: ReadonlyMap<string, number>,
32	): ZeroBasedState {
33	  const budgetedIncomeCents = incomeEnvelopes.reduce((s, i) => s + i.budgetedCents, 0);
34	  let allocatedCents = 0;
35	  for (const v of allocationsByEnv.values()) allocatedCents += v;
36	  const unallocatedCents = budgetedIncomeCents - allocatedCents;
37	  return {
38	    budgetedIncomeCents,
39	    allocatedCents,
40	    unallocatedCents,
41	    zeroBasedAlert: unallocatedCents !== 0,
42	  };
43	}
44	
45	export interface IncomeVariance {
