572	    // per envelope per calendar month (in the budget timezone).
573	    const movementByMonth = new Map<string, Map<string, number>>();
574	    for (const m of movements) {
575	      const key = todayISO(this.tz, new Date(m.ts)).slice(0, 7);
576	      let bucket = movementByMonth.get(key);
577	      if (bucket === undefined) {
578	        bucket = new Map<string, number>();
579	        movementByMonth.set(key, bucket);
580	      }
581	      bucket.set(m.fromEnvelopeId, (bucket.get(m.fromEnvelopeId) ?? 0) - m.amountCents);
582	      bucket.set(m.toEnvelopeId, (bucket.get(m.toEnvelopeId) ?? 0) + m.amountCents);
583	    }
584	    const movementFor = (p: Period, envelopeId: string): number =>
585	      movementByMonth.get(periodKey(p))?.get(envelopeId) ?? 0;
586	
587	    // Roll-forward carryover (owner directive 2026-08-12: "the left value should
588	    // always be how much is left in the envelope — it should roll over"). Each
589	    // stored baseline is the OPENING carryover of its capture month
590	    // (carryoverAnchor: the last manual reset, or the initial import; falls back
591	    // to rolloverStart for baselines never explicitly captured). The fold
592	    // advances it to range.from applying (budget + activity + movements) per
593	    // intervening month under the envelope's rollover rule — so a July charge
594	    // draws an August carryover down, and unspent budget rolls forward.
595	    // Allocation for an intervening month comes from its materialised rows when
596	    // the month exists (they carry this-month overrides and prorations), else
597	    // from template resolution.
598	    const ruleByEnv = new Map(envelopes.map((e) => [e.id, normaliseRolloverRule(e.rolloverRule)]));
599	    const preFoldEnvs = envelopeCarryover.filter((c) => {
600	      const anchor = c.carryoverAnchor ?? c.rolloverStart;
601	      return anchor !== null && comparePeriods(periodOfDate(anchor), range.from) < 0;
602	    });
603	    let preFoldStart = range.from;
604	    for (const c of preFoldEnvs) {
605	      const p = periodOfDate((c.carryoverAnchor ?? c.rolloverStart)!);
606	      if (comparePeriods(p, preFoldStart) < 0) preFoldStart = p;
607	    }
608	    const preAllocByMonth = new Map<string, ReadonlyMap<string, number>>();
609	    const preActivityByMonth = new Map<string, ReadonlyMap<string, number>>();
