611	      if (comparePeriods(p, range.from) >= 0) break; // months strictly before range.from
612	      const rows = await this.store.listAllocations(userId, periodKey(p));
613	      if (rows.length > 0) {
614	        const byEnv = new Map<string, number>();
615	        for (const a of rows) byEnv.set(a.envelopeId, (byEnv.get(a.envelopeId) ?? 0) + a.amountCents);
616	        preAllocByMonth.set(periodKey(p), byEnv);
617	      } else {
618	        preAllocByMonth.set(periodKey(p), resolveTemplateForMonth(template, p));
619	      }
620	      preActivityByMonth.set(periodKey(p), computeActivity(txs, mappings, this.config, { period: p }).byEnvelope);
