638	          const act = preActivityByMonth.get(periodKey(m))?.get(c.envelopeId) ?? 0;
639	          const left = carry + alloc + act + movementFor(m, c.envelopeId);
640	          carry = carryoverInto(rule, left, nextPeriod(m));
