// signed activity on BOTH envelopes — a line item, never a budget edit. Net
// per envelope per calendar month (in the budget timezone).
const movementByMonth = new Map<string, Map<string, number>>();
for (const m of movements) {
  const key = todayISO(this.tz, new Date(m.ts)).slice(0, 7);
  let bucket = movementByMonth.get(key);
  if (bucket === undefined) {
    bucket = new Map<string, number>();
    movementByMonth.set(key, bucket);
  }
  bucket.set(m.fromEnvelopeId, (bucket.get(m.fromEnvelopeId) ?? 0) - m.amountCents);
  bucket.set(m.toEnvelopeId, (bucket.get(m.toEnvelopeId) ?? 0) + m.amountCents);
}
const movementFor = (p: Period, envelopeId: string): number =>
  movementByMonth.get(periodKey(p))?.get(envelopeId) ?? 0;

// Roll-forward carryover (owner directive 2026-08-12: "the left value should
// always be how much is left in the envelope — it should roll over"). Each
// stored baseline is the OPENING carryover of its capture month
// (carryoverAnchor: the last manual reset, or the initial import; falls back
// to rolloverStart for baselines never explicitly captured). The fold
// advances it to range.from applying (budget + activity + movements) per
// intervening month under the envelope's rollover rule — so a July charge
// draws an August carryover down, and unspent budget rolls forward.
// Allocation for an intervening month comes from its materialised rows when
// the month exists (they carry this-month overrides and prorations), else
// from template resolution.
const ruleByEnv = new Map(envelopes.map((e) => [e.id, normaliseRolloverRule(e.rolloverRule)]));
const preFoldEnvs = envelopeCarryover.filter((c) => {
  const anchor = c.carryoverAnchor ?? c.rolloverStart;
  return anchor !== null && comparePeriods(periodOfDate(anchor), range.from) < 0;
});
let preFoldStart = range.from;
for (const c of preFoldEnvs) {
  const p = periodOfDate((c.carryoverAnchor ?? c.rolloverStart)!);
  if (comparePeriods(p, preFoldStart) < 0) preFoldStart = p;
}
const preAllocByMonth = new Map<string, ReadonlyMap<string, number>>();
const preActivityByMonth = new Map<string, ReadonlyMap<string, number>>();
for (const p of periodRange(preFoldStart, range.from)) {
  if (comparePeriods(p, range.from) >= 0) break; // months strictly before range.from
  const rows = await this.store.listAllocations(userId, periodKey(p));
