export const ALLOCATIONS_UNIQUE_INDEX_SQL =
  `CREATE UNIQUE INDEX IF NOT EXISTS idx_alloc_user_env_period
   ON allocations(user_id, envelope_id, period)`;

/**
 * Garbage-era purge (2026-08-12). Unvalidated from/to query params let partial
 * years typed into browser date inputs (year 0002, 0020, ...) reach ensureMonth,
 * which materialised ~1.4M allocation rows (and matching sync-roll history) for
 * years 10..1015 — most of the database's bulk. Handlers now validate dates and
 * ensureMonth carries an era guard; these statements remove the debris. The
 * era bounds are deliberately generous (1990..2100); real data is 2024+.
 * Idempotent: a clean database matches zero rows.
 */
export const GARBAGE_ALLOCATIONS_COUNT_SQL =
  `SELECT COUNT(*) AS n FROM allocations WHERE period < '2023-01' OR period > '2030-12'`;

/**
 * Legacy-line truth backfill (2026-08-12, owner request: "show the actual start
 * date"). Open-ended 1970 template lines predate versioning; their REAL start
 * is knowable — an expense budget begins at its earliest materialised month,
 * an income budget at its rollover anchor. Before backfilling, allocation rows
 * for months before the tenant's first transaction (typo-era artifacts with no
 * activity) are removed so "earliest materialised month" means real history.
 * All statements are portable and idempotent (they only match 1970-open lines
 * / pre-history rows).
 */
export const LEGACY_START_BACKFILL_SQL: readonly string[] = [
  // A: allocations for months before the tenant's first transaction month.
  //    (NULL first-month — no transactions — compares NULL: nothing deleted.)
  `DELETE FROM allocations WHERE period < (
     SELECT substr(MIN(t.txn_date), 1, 7) FROM transactions t WHERE t.user_id = allocations.user_id
   )`,
  // B: expense-family open-1970 lines -> earliest remaining materialised month.
  `UPDATE budget_template SET effective_from = (
     SELECT MIN(a.period) || '-01' FROM allocations a
     WHERE a.user_id = budget_template.user_id AND a.envelope_id = budget_template.envelope_id
   )
   WHERE effective_from = '1970-01-01' AND effective_to IS NULL
     AND EXISTS (
       SELECT 1 FROM allocations a2
       WHERE a2.user_id = budget_template.user_id AND a2.envelope_id = budget_template.envelope_id
     )`,
  // C: income open-1970 lines -> the income's rollover anchor.
  `UPDATE budget_template SET effective_from = (
     SELECT ie.rollover_start FROM income_envelopes ie
     WHERE ie.user_id = budget_template.user_id AND ie.id = budget_template.envelope_id
   )
   WHERE effective_from = '1970-01-01' AND effective_to IS NULL
     AND EXISTS (
       SELECT 1 FROM income_envelopes ie2
       WHERE ie2.user_id = budget_template.user_id AND ie2.id = budget_template.envelope_id
         AND ie2.rollover_start IS NOT NULL
     )`,
  // D: anything still open-1970 (e.g. an envelope created into an already-
  //    materialised month, so it never gained an allocation row) -> its
  //    creation anchor (envelopes.rollover_start, stamped at create time).
  `UPDATE budget_template SET effective_from = (
     SELECT e.rollover_start FROM envelopes e
     WHERE e.user_id = budget_template.user_id AND e.id = budget_template.envelope_id
   )
   WHERE effective_from = '1970-01-01' AND effective_to IS NULL
     AND EXISTS (
       SELECT 1 FROM envelopes e2
       WHERE e2.user_id = budget_template.user_id AND e2.id = budget_template.envelope_id
         AND e2.rollover_start IS NOT NULL
     )`,
];

