/**
 * Recurring template auto-roll and budget history (ISC-29, ISC-76, ISC-77).
 */

import { describe, test, expect } from "bun:test";
import { MemoryStore } from "./penny-memory-store.ts";
import { EnvelopeService } from "../src/envelope/service.ts";
import { BudgetService } from "../src/budget/service.ts";
import { env, USER, CONFIG } from "./penny-fixtures.ts";

const JUN = { year: 2026, month: 6 };
const JUL = { year: 2026, month: 7 };

async function seed() {
  const store = new MemoryStore();
  await store.upsertEnvelope(USER, env("groceries", { name: "Groceries" }));
  await store.upsertEnvelope(USER, env("rent", { name: "Rent" }));
  await store.putTemplateLine(USER, { id: "t1", userId: USER, envelopeId: "groceries", amountCents: 50000 });
  await store.putTemplateLine(USER, { id: "t2", userId: USER, envelopeId: "rent", amountCents: 200000 });
  const envSvc = new EnvelopeService(store, CONFIG);
  const budget = new BudgetService(store, envSvc);
  return { store, envSvc, budget };
}

describe("template auto-roll (ISC-29, ISC-76)", () => {
  test("a new month is never blank: the template auto-applies with no manual step", async () => {
    const { store, budget } = await seed();
    const res = await budget.ensureMonth(USER, JUN);
    expect(res.rolled).toBe(2);

    const allocs = await store.listAllocations(USER, "2026-06");
    const byEnv = new Map(allocs.map((a) => [a.envelopeId, a.amountCents]));
    expect(byEnv.get("groceries")).toBe(50000);
    expect(byEnv.get("rent")).toBe(200000);
  });

  test("every auto-roll is recorded in the budget history with before/after (ISC-77)", async () => {
    const { store, budget } = await seed();
    await budget.ensureMonth(USER, JUN);
    const history = await store.listBudgetHistory(USER);
    expect(history.length).toBe(2);
    const groceries = history.find((h) => h.envelopeId === "groceries")!;
    expect(groceries.beforeCents).toBe(0);
    expect(groceries.afterCents).toBe(50000);
    expect(groceries.actor).toBe("sync");
  });

  test("auto-roll is idempotent: a populated month is not clobbered", async () => {
    const { store, budget } = await seed();
    await budget.ensureMonth(USER, JUN);
    const second = await budget.ensureMonth(USER, JUN);
    expect(second.rolled).toBe(0);
    expect((await store.listAllocations(USER, "2026-06")).length).toBe(2);
  });

  test("the template rolls forward into each subsequent month (ISC-29)", async () => {
    const { store, budget } = await seed();
    await budget.ensureMonth(USER, JUN);
    await budget.ensureMonth(USER, JUL);
    const jul = await store.listAllocations(USER, "2026-07");
    expect(new Map(jul.map((a) => [a.envelopeId, a.amountCents])).get("rent")).toBe(200000);
  });
});

