      // 409 with the conflicts so the client can prompt and retry with
      // supersedeScheduled (scheduled budgets are never destroyed implicitly).
      if (err instanceof ScheduledConflictError) {
        return c.json({ error: err.message, code: "scheduled_conflict", conflicts: err.conflicts }, 409);
      }
      throw err;
    }
  });
